options.afterRender:
const el = context.element;
if (!el) return;

el.style.height = '100%';
el.style.display = 'flex';
el.style.flexDirection = 'column';
if (el.parentElement) {
  el.parentElement.style.height = '100%';
}

// 1. SINGLETON LIFECYCLE: Kill any prior animation loop or clock to prevent duplicate threads and CPU thrashing
if (window.__imsDrillAnimId) {
  cancelAnimationFrame(window.__imsDrillAnimId);
  window.__imsDrillAnimId = null;
}
if (window.__imsDrillClockInterval) {
  clearInterval(window.__imsDrillClockInterval);
  window.__imsDrillClockInterval = null;
}

window.__imsDrillAutoScrollEnabled = true;

const grid = el.querySelector('#drill-cards-grid');

// 2. SCROLL RESTORATION ACROSS REFRESHES:
// Every refresh rebuilds the grid at scrollLeft 0. The position is saved on every
// scroll event (wheel, drag, scrollbar, trackpad, keyboard, auto-scroll) in a
// window global and in sessionStorage (survives a page reload), and put back here.
const SCROLL_KEY = 'ims.drilling.fleet.scrollLeft';
let restoring = false;
// the window global is updated on every event; sessionStorage at most every 250 ms,
// with a trailing write so the final position is never the one skipped
const storeScroll = () => {
  window.__imsDrillScrollTimer = null;
  try { sessionStorage.setItem(SCROLL_KEY, String(Math.round(window.__imsDrillLastScrollLeft || 0))); } catch (e) { /* storage blocked */ }
};
const saveScroll = (x, force) => {
  window.__imsDrillLastScrollLeft = x;
  if (force) {
    if (window.__imsDrillScrollTimer) clearTimeout(window.__imsDrillScrollTimer);
    storeScroll();
  } else if (!window.__imsDrillScrollTimer) {
    window.__imsDrillScrollTimer = setTimeout(storeScroll, 250);
  }
};
let savedScroll = window.__imsDrillLastScrollLeft;
if (typeof savedScroll !== 'number') {
  try { savedScroll = parseInt(sessionStorage.getItem(SCROLL_KEY), 10) || 0; } catch (e) { savedScroll = 0; }
  window.__imsDrillLastScrollLeft = savedScroll;
}
// Only a freshly built grid (scrollLeft 0) is restored. When the refresh kept the
// element, it is already where the user left it, and writing the saved value back
// could undo a scroll whose event has not been dispatched yet.
if (grid && savedScroll > 0 && grid.scrollLeft < 1) {
  grid.scrollLeft = savedScroll;
  const applied = grid.scrollLeft;
  // Layout may not be complete yet, so that assignment can be clamped short.
  // Retry once after layout -- but only if nothing has moved the grid since,
  // so a scroll the user makes right after a refresh is never pulled back.
  if (applied < savedScroll - 5) {
    restoring = true;
    requestAnimationFrame(() => requestAnimationFrame(() => {
      restoring = false;
      if (grid && Math.abs(grid.scrollLeft - applied) <= 1) grid.scrollLeft = savedScroll;
    }));
  }
}
const handleScroll = () => {
  // while a clamped restore is pending, a move away from the clamped value is the user's
  if (!grid || (restoring && grid.scrollLeft <= savedScroll)) return;
  saveScroll(grid.scrollLeft, false);
};

window.__imsSetFilter = function(filter) {
  saveScroll(0, true);
  if (grid) grid.scrollLeft = 0;
  if (context.grafana && context.grafana.locationService && typeof context.grafana.locationService.partial === 'function') {
    context.grafana.locationService.partial({
      '${__url_time_range}': null,
      '%24%7B__url_time_range%7D': null,
      'var-status_filter': filter
    });
  } else {
    const p = new URLSearchParams(window.location.search);
    p.delete('${__url_time_range}');
    p.delete('%24%7B__url_time_range%7D');
    p.set('var-status_filter', filter);
    window.history.pushState({}, '', window.location.pathname + '?' + p.toString() + window.location.hash);
    window.dispatchEvent(new PopStateEvent('popstate'));
  }
};

window.__imsGoToMachine = function(machine) {
  const currentParams = new URLSearchParams(window.location.search);
  const from = currentParams.get('from') || 'now-30d';
  const to = currentParams.get('to') || 'now';
  const factories = currentParams.getAll('var-factory');
  const factoryParam = factories.length > 0 ? factories.map(f => '&var-factory=' + encodeURIComponent(f)).join('') : '';
  const targetUrl = `/d/ims-drilling-machine-detail/ims-drilling-e28094-2-machine-investigation?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&var-focus_machine=${encodeURIComponent(machine)}${factoryParam}`;

  if (context.grafana && context.grafana.locationService && typeof context.grafana.locationService.push === 'function') {
    context.grafana.locationService.push(targetUrl);
  } else {
    window.location.href = targetUrl;
  }
};

let pauseUntil = 0;

const handleClick = (e) => {
  const pill = e.target.closest('.drill-fpill[data-filter], .drill-kpi-card[data-filter]');
  if (pill) {
    e.preventDefault();
    e.stopPropagation();
    const filter = pill.getAttribute('data-filter');
    if (filter) window.__imsSetFilter(filter);
    return;
  }
  const machine = e.target.closest('.drill-m-name');
  if (machine) {
    e.preventDefault();
    e.stopPropagation();
    const m = machine.getAttribute('data-machine');
    if (m) {
      if (window.__imsGoToMachine) {
        window.__imsGoToMachine(m);
      } else {
        const currentParams = new URLSearchParams(window.location.search);
        const from = currentParams.get('from') || 'now-30d';
        const to = currentParams.get('to') || 'now';
        window.location.href = `/d/ims-drilling-machine-detail/ims-drilling-e28094-2-machine-investigation?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}&var-focus_machine=${encodeURIComponent(m)}&var-machine_id=${encodeURIComponent(m)}`;
      }
    }
    return;
  }
};

const updateClock = () => {
  const clockEl = el.querySelector('#drill-live-datetime');
  if (clockEl) {
    const now = new Date();
    const optDate = { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Bangkok' };
    const optTime = { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: 'Asia/Bangkok' };
    const d = now.toLocaleDateString('en-GB', optDate);
    const t = now.toLocaleTimeString('en-GB', optTime);
    clockEl.textContent = `${d} • ${t} `;
  }
};
updateClock();
window.__imsDrillClockInterval = setInterval(updateClock, 1000);

// --- HARDWARE-ACCELERATED VSYNC AUTO-SCROLL ENGINE ---
let isHovered = false;

const handleMouseEnter = (e) => {
  if (e.target.closest('.drill-m-card')) {
    isHovered = true;
  }
};
const handleMouseLeave = (e) => {
  if (e.target.closest('.drill-m-card')) {
    isHovered = false;
    pauseUntil = Date.now() + 2000;
  }
};
const handleWheel = (e) => {
  if (!grid) return;
  if (e.deltaY !== 0) {
    grid.scrollLeft += e.deltaY;
    window.__imsDrillLastScrollLeft = grid.scrollLeft;
    pauseUntil = Date.now() + 5000;
  }
};

// Drag-to-scroll interaction
let isDown = false;
let startX = 0;
let scrollStart = 0;

const handleMouseDown = (e) => {
  if (!grid) return;
  if (e.target.closest('a, button, .drill-m-name, .drill-status-pill')) return;
  isDown = true;
  startX = e.pageX - grid.offsetLeft;
  scrollStart = grid.scrollLeft;
  pauseUntil = Date.now() + 6000;
};
const handleMouseUp = () => { 
  isDown = false; 
  if (grid) window.__imsDrillLastScrollLeft = grid.scrollLeft;
};
const handleMouseMove = (e) => {
  if (!isDown || !grid) return;
  e.preventDefault();
  const x = e.pageX - grid.offsetLeft;
  const walk = (x - startX) * 1.5;
  grid.scrollLeft = scrollStart - walk;
  window.__imsDrillLastScrollLeft = grid.scrollLeft;
  pauseUntil = Date.now() + 6000;
};

el.addEventListener('mouseenter', handleMouseEnter, true);
el.addEventListener('mouseleave', handleMouseLeave, true);
if (grid) {
  grid.addEventListener('scroll', handleScroll, { passive: true });
  grid.addEventListener('wheel', handleWheel, { passive: true });
  grid.addEventListener('mousedown', handleMouseDown);
  window.addEventListener('mouseup', handleMouseUp);
  grid.addEventListener('mousemove', handleMouseMove);
}

let lastTime = performance.now();
let scrollAccumulator = 0;
const SCROLL_SPEED_PX_PER_SEC = 25; // Smooth cinematic glide

const scrollLoop = (now) => {
  window.__imsDrillAnimId = requestAnimationFrame(scrollLoop);

  // Anti-jitter: clamp delta to 33ms max so a GC/DOM-reflow pause never creates a violent multi-pixel leap
  const rawDelta = (now - lastTime) / 1000;
  const delta = Math.min(Math.max(rawDelta, 0), 0.033);
  lastTime = now;

  if (!window.__imsDrillAutoScrollEnabled) return;
  if (isHovered || isDown) return;
  if (Date.now() < pauseUntil) return;
  if (!grid) return;

  const maxX = grid.scrollWidth - grid.clientWidth;
  if (maxX <= 10) return; // Layout not ready yet

  if (grid.scrollLeft >= maxX - 2) {
    pauseUntil = Date.now() + 5000;
    grid.scrollTo({ left: 0, behavior: 'smooth' });
    saveScroll(0, true);
    return;
  }

  scrollAccumulator += delta * SCROLL_SPEED_PX_PER_SEC;
  if (scrollAccumulator >= 1) {
    const px = Math.floor(scrollAccumulator);
    grid.scrollLeft += px;
    scrollAccumulator -= px;
    window.__imsDrillLastScrollLeft = grid.scrollLeft;
  }
};

window.__imsDrillAnimId = requestAnimationFrame(scrollLoop);

el.addEventListener('click', handleClick);

return () => {
  if (window.__imsDrillAnimId) cancelAnimationFrame(window.__imsDrillAnimId);
  if (window.__imsDrillClockInterval) clearInterval(window.__imsDrillClockInterval);
  el.removeEventListener('click', handleClick);
  el.removeEventListener('mouseenter', handleMouseEnter, true);
  el.removeEventListener('mouseleave', handleMouseLeave, true);
  if (grid) {
    grid.removeEventListener('scroll', handleScroll);
    grid.removeEventListener('wheel', handleWheel);
    grid.removeEventListener('mousedown', handleMouseDown);
    window.removeEventListener('mouseup', handleMouseUp);
    grid.removeEventListener('mousemove', handleMouseMove);
  }
};

options.styles:
.drill-container {
font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
color: #E2E8F0;
background: transparent;
padding: 0;
box-sizing: border-box;
display: flex;
flex-direction: column;
height: 100%;
width: 100%;
overflow: hidden;
contain: layout;
}

.drill-pinned-section {
position: -webkit-sticky;
position: sticky;
top: 0;
z-index: 50;
background: #111217;
padding-top: 2px;
padding-bottom: 6px;
margin-bottom: 6px;
flex-shrink: 0;
border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.drill-header {
background: #14171D;
border-radius: 8px;
padding: 8px 16px;
display: flex;
justify-content: space-between;
align-items: center;
margin-bottom: 6px;
border: 1px solid #232731;
box-shadow: 0 4px 14px rgba(0,0,0,0.35);
flex-wrap: wrap;
gap: 8px;
}

.drill-header-left h1 {
margin: 0;
font-size: 18px;
font-weight: 800;
color: #F8FAFC;
letter-spacing: -0.01em;
display: flex;
align-items: center;
gap: 8px;
}

.drill-header-datetime {
margin-top: 2px;
font-family: 'JetBrains Mono', monospace;
font-size: 11.5px;
font-weight: 500;
color: #94A3B8;
letter-spacing: 0.02em;
}

.drill-filter-pills {
display: flex;
align-items: center;
gap: 6px;
flex-wrap: wrap;
}

.drill-filter-label {
font-size: 10.5px;
font-weight: 700;
color: #94A3B8;
text-transform: uppercase;
margin-right: 2px;
}

.drill-fpill {
padding: 4px 10px;
border-radius: 6px;
font-size: 11px;
font-weight: 700;
text-decoration: none;
transition: all 0.15s ease;
border: 1px solid #2F3542;
background: #1E222A;
color: #94A3B8;
display: inline-flex;
align-items: center;
gap: 4px;
}

.drill-fpill:hover {
transform: translateY(-1px);
color: #FFFFFF;
}

.drill-fpill.is-active {
font-weight: 700;
color: #FFFFFF !important;
box-shadow: none !important;
transform: none !important;
}

.drill-fpill.fpill-all.is-active { background: #2563EB !important; border-color: #2563EB !important; color: #FFFFFF !important; }
.drill-fpill.fpill-run.is-active { background: #059669 !important; border-color: #059669 !important; color: #FFFFFF !important; }
.drill-fpill.fpill-alarm.is-active { background: #DC2626 !important; border-color: #DC2626 !important; color: #FFFFFF !important; }
.drill-fpill.fpill-tool.is-active { background: #D97706 !important; border-color: #D97706 !important; color: #FFFFFF !important; }
.drill-fpill.fpill-stop.is-active { background: #D97706 !important; border-color: #D97706 !important; color: #FFFFFF !important; }
.drill-fpill.fpill-standby.is-active { background: #475569 !important; border-color: #475569 !important; color: #FFFFFF !important; }
.drill-fpill.fpill-offline.is-active { background: #334155 !important; border-color: #64748B !important; color: #FFFFFF !important; }

.drill-scroll-toggle {
margin-left: 4px;
cursor: pointer;
border-color: #3B82F6;
color: #60A5FA;
}
.drill-scroll-toggle.is-active {
background: rgba(59, 130, 246, 0.2) !important;
border-color: #3B82F6 !important;
color: #93C5FD !important;
box-shadow: 0 0 8px rgba(59, 130, 246, 0.25);
}
.drill-scroll-toggle.is-paused {
background: #1E222A !important;
border-color: #475569 !important;
color: #94A3B8 !important;
box-shadow: none !important;
}

.drill-kpi-row {
display: grid;
grid-template-columns: repeat(8, minmax(0, 1fr));
gap: 7px;
margin-bottom: 2px;
}

.drill-kpi-card {
background: #14171D;
border-radius: 6px;
padding: 8px 5px;
text-align: center;
border: 1px solid #232731;
box-shadow: 0 2px 8px rgba(0,0,0,0.25);
transition: transform 0.15s, border-color 0.15s;
cursor: pointer;
}
.drill-kpi-card.is-active {
background: #1C2333;
border-color: #60A5FA;
box-shadow: 0 0 10px rgba(59, 130, 246, 0.35);
}
.drill-kpi-card:hover {
transform: translateY(-1px);
border-color: #374151;
}

.drill-kpi-card.kpi-total { border-top: 3px solid #3B82F6; }
.drill-kpi-card.kpi-run { border-top: 3px solid #10B981; }
.drill-kpi-card.kpi-toolchange { border-top: 3px solid #EAB308; }
.drill-kpi-card.kpi-stop { border-top: 3px solid #F59E0B; }
.drill-kpi-card.kpi-alarm { border-top: 3px solid #EF4444; }
.drill-kpi-card.kpi-standby { border-top: 3px solid #64748B; }
.drill-kpi-card.kpi-offline { border-top: 3px solid #94A3B8; }
.drill-kpi-card.kpi-tool { border-top: 3px solid #06B6D4; }

.drill-kpi-title {
font-size: 8.5px;
font-weight: 700;
color: #94A3B8;
letter-spacing: 0.04em;
text-transform: uppercase;
margin-bottom: 2px;
white-space: nowrap;
overflow: hidden;
text-overflow: ellipsis;
}
.drill-kpi-val {
font-size: 19px;
font-weight: 800;
line-height: 1.1;
margin-bottom: 2px;
}
.kpi-total .drill-kpi-val { color: #F8FAFC; }
.kpi-run .drill-kpi-val { color: #34D399; }
.kpi-toolchange .drill-kpi-val { color: #FDE047; }
.kpi-stop .drill-kpi-val { color: #FBBF24; }
.kpi-alarm .drill-kpi-val { color: #F87171; }
.kpi-standby .drill-kpi-val { color: #CBD5E1; }
.kpi-offline .drill-kpi-val { color: #94A3B8; }
.kpi-tool .drill-kpi-val { color: #38BDF8; }

.drill-kpi-desc {
font-size: 8.5px;
color: #64748B;
white-space: nowrap;
overflow: hidden;
text-overflow: ellipsis;
}

/* HORIZONTAL CARDS WRAPPER & 2-ROW GRID */
.drill-cards-wrapper {
position: relative;
flex: 1 1 auto;
display: flex;
overflow: hidden;
min-height: 0;
width: 100%;
}

.drill-cards-grid {
display: grid;
grid-template-rows: repeat(2, minmax(0, 1fr));
grid-auto-flow: column;
grid-auto-columns: 310px;
gap: 8px;
overflow-x: auto;
overflow-y: hidden;
padding: 2px 4px 6px 4px;
width: 100%;
height: 100%;
box-sizing: border-box;
scroll-behavior: auto;
overflow-anchor: none;
user-select: none;
cursor: grab;
scrollbar-width: thin;
scrollbar-color: #3B82F6 #14171D;
}

.drill-cards-grid:active {
cursor: grabbing;
}

.drill-cards-grid::-webkit-scrollbar {
height: 6px;
}
.drill-cards-grid::-webkit-scrollbar-track {
background: #14171D;
border-radius: 3px;
}
.drill-cards-grid::-webkit-scrollbar-thumb {
background: #2D3748;
border-radius: 3px;
border: 1px solid #1E222A;
}
.drill-cards-grid::-webkit-scrollbar-thumb:hover {
background: #3B82F6;
}



/* COMPACT INDUSTRIAL MACHINE CARD (KIOSK OPTIMIZED) */
.drill-m-card {
background: #14171D;
border-radius: 8px;
padding: 6px 10px;
border: 1.5px solid #232731;
display: flex;
flex-direction: column;
justify-content: space-between;
box-shadow: 0 2px 8px rgba(0,0,0,0.25);
transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
height: 100%;
min-height: 0;
box-sizing: border-box;
contain: layout style;
}

.drill-m-card:hover {
transform: translateY(-2px);
box-shadow: 0 6px 16px rgba(0,0,0,0.45);
}

.drill-m-card.state-run {
border-color: rgba(16, 185, 129, 0.45);
box-shadow: 0 2px 8px rgba(16, 185, 129, 0.08);
}
.drill-m-card.state-alarm {
border-color: rgba(239, 68, 68, 0.85);
box-shadow: 0 0 14px rgba(239, 68, 68, 0.25);
background: linear-gradient(180deg, rgba(239, 68, 68, 0.1) 0%, #14171D 35%);
}
.drill-m-card.state-stop {
border-color: rgba(245, 158, 11, 0.5);
box-shadow: 0 2px 8px rgba(245, 158, 11, 0.08);
}
.drill-m-card.state-warning {
border-color: rgba(234, 179, 8, 0.5);
}
.drill-m-card.state-standby {
border-color: rgba(100, 116, 139, 0.4);
box-shadow: 0 2px 8px rgba(100, 116, 139, 0.05);
}
.drill-m-card.state-offline {
border: 1.5px dashed rgba(100, 116, 139, 0.4);
background: #101217;
opacity: 0.85;
box-shadow: 0 2px 6px rgba(0,0,0,0.2);
}
.drill-m-card.state-offline:hover {
opacity: 1;
border-color: #64748B;
}

.drill-card-header {
display: flex;
align-items: center;
justify-content: space-between;
margin-bottom: 3px;
}
.drill-m-title {
display: flex;
align-items: center;
gap: 6px;
}
.drill-m-name {
font-size: 14px;
font-weight: 800;
color: #F8FAFC;
text-decoration: none;
cursor: pointer;
font-family: 'JetBrains Mono', monospace;
transition: color 0.15s ease;
}
.drill-m-name:hover {
color: #38BDF8;
text-decoration: underline;
}

.drill-status-pill {
font-size: 9.5px;
font-weight: 700;
padding: 1px 6px;
border-radius: 8px;
display: inline-flex;
align-items: center;
gap: 4px;
}
.drill-status-pill::before {
content: '';
width: 5px;
height: 5px;
border-radius: 50%;
display: inline-block;
}
.state-run .drill-status-pill { background: rgba(16, 185, 129, 0.2); color: #34D399; }
.state-run .drill-status-pill::before { background: #10B981; }
.state-alarm .drill-status-pill { background: rgba(239, 68, 68, 0.25); color: #F87171; }
.state-alarm .drill-status-pill::before { background: #EF4444; }
.state-stop .drill-status-pill { background: rgba(245, 158, 11, 0.2); color: #FBBF24; }
.state-stop .drill-status-pill::before { background: #F59E0B; }
.state-warning .drill-status-pill { background: rgba(234, 179, 8, 0.2); color: #FDE047; }
.state-warning .drill-status-pill::before { background: #EAB308; }
.state-standby .drill-status-pill { background: rgba(100, 116, 139, 0.2); color: #94A3B8; }
.state-standby .drill-status-pill::before { background: #64748B; }
.state-offline .drill-status-pill { background: rgba(100, 116, 139, 0.18); color: #94A3B8; border: 1px solid rgba(100, 116, 139, 0.35); }
.state-offline .drill-status-pill::before { background: #64748B; }

.drill-m-timeago {
font-size: 9.5px;
color: #94A3B8;
font-weight: 600;
}
.state-offline .drill-m-timeago {
color: #F97316;
font-weight: 700;
}

/* DETAILS TABLE */
.drill-detail-table {
display: flex;
flex-direction: column;
gap: 1.5px;
font-size: 11px;
margin-bottom: 2px;
}
.drill-detail-row {
display: grid;
grid-template-columns: 82px 1fr;
align-items: baseline;
gap: 4px;
}
.drill-detail-label {
color: #94A3B8;
font-weight: 500;
font-size: 10.5px;
}
.drill-detail-val {
color: #E2E8F0;
font-weight: 600;
white-space: nowrap;
overflow: hidden;
text-overflow: ellipsis;
}
.drill-code-val {
font-family: 'JetBrains Mono', monospace;
font-weight: 700;
}
.state-alarm .drill-code-val { color: #F87171; }
.state-run .drill-code-val { color: #34D399; }
.state-stop .drill-code-val { color: #FBBF24; }
.state-offline .drill-code-val { color: #94A3B8; }

.drill-prog-val { font-family: 'JetBrains Mono', monospace; color: #38BDF8; font-weight: 600; font-size: 10.5px; }
.drill-hole-val { font-family: 'JetBrains Mono', monospace; color: #FBBF24; font-weight: 700; font-size: 10.5px; }
.drill-tool-val { color: #F1F5F9; font-weight: 600; }
.drill-msg-row {
grid-template-columns: 52px 1fr;
align-items: flex-start;
margin-top: 1px;
}
.drill-msg-val {
color: #CBD5E1;
font-size: 10px;
white-space: normal !important;
word-break: break-word;
line-height: 1.25;
min-height: 25px;
max-height: 38px;
overflow-y: auto;
scrollbar-width: none;
}
.drill-msg-val::-webkit-scrollbar { display: none; }
.state-alarm .drill-msg-val { color: #FECACA; font-weight: 600; }
.drill-time-val { font-family: 'JetBrains Mono', monospace; font-weight: 700; color: #38BDF8; font-size: 10.5px; }

/* SPINDLES */
.drill-spindle-box {
margin: 2px 0 3px 0;
display: flex;
flex-direction: column;
gap: 2.5px;
}
.drill-spindle-header {
font-size: 9.5px;
font-weight: 600;
color: #94A3B8;
display: flex;
align-items: center;
justify-content: space-between;
}
.drill-spindle-sub {
font-size: 8.5px;
color: #64748B;
font-family: 'JetBrains Mono', monospace;
}
.drill-spindle-badges {
display: flex;
align-items: center;
gap: 5px;
}
.drill-spindle-circle {
width: 16px;
height: 16px;
border-radius: 50%;
display: inline-flex;
align-items: center;
justify-content: center;
font-size: 9px;
font-weight: 800;
font-family: 'JetBrains Mono', monospace;
user-select: none;
box-sizing: border-box;
transition: all 0.2s ease;
}
.drill-spindle-circle.is-on {
background: radial-gradient(circle at 45% 38%, #86EFAC 0%, #22C55E 45%, #15803D 85%, #14532D 100%);
border: 1px solid #14532D;
color: #064E3B;
box-shadow: 0 0 3px rgba(34, 197, 94, 0.4);
}
.drill-spindle-circle.is-off {
background: radial-gradient(circle at 45% 38%, #4A171E 0%, #2A0E13 100%);
border: 1px solid #661D26;
color: #D19CA4;
box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
}
.drill-spindle-circle.is-alarm {
background: radial-gradient(circle at 45% 38%, #FECACA 0%, #EF4444 45%, #B91C1C 85%, #7F1D1D 100%);
border: 1px solid #7F1D1D;
color: #FFFFFF;
text-shadow: 0 1px 2px rgba(0, 0, 0, 0.7);
box-shadow: 0 0 6px rgba(239, 68, 68, 0.6);
}

/* MID PILLS (RPM & FEED) */
.drill-mid-pills {
display: flex;
justify-content: space-around;
align-items: center;
gap: 6px;
margin-bottom: 3px;
background: #0E1014;
padding: 3px 6px;
border-radius: 4px;
border: 1px solid #1E222A;
}
.drill-pill-tag {
font-size: 9.5px;
color: #94A3B8;
font-weight: 600;
}
.drill-pill-val-rpm {
color: #38BDF8;
font-family: 'JetBrains Mono', monospace;
font-weight: 700;
}
.drill-pill-val-feed {
color: #34D399;
font-family: 'JetBrains Mono', monospace;
font-weight: 700;
}
.drill-pill-sep {
color: #334155;
font-weight: 700;
}

/* FOOTER */
.drill-card-footer {
display: flex;
align-items: center;
padding-top: 3px;
border-top: 1px solid #232731;
font-size: 10px;
}
.drill-footer-last {
color: #CBD5E1;
font-family: 'JetBrains Mono', monospace;
font-size: 9.5px;
display: flex;
align-items: center;
gap: 3px;
}
.drill-footer-last strong {
color: #F8FAFC;
font-weight: 700;
}
.drill-footer-ago {
color: #94A3B8;
font-weight: 600;
font-size: 9px;
background: rgba(255, 255, 255, 0.06);
padding: 1px 4px;
border-radius: 3px;
}

/* EMPTY STATE */
.drill-empty-fleet {
grid-column: 1 / -1;
background: #14171D;
border: 1px solid #232731;
border-radius: 10px;
padding: 40px 20px;
text-align: center;
box-shadow: 0 4px 16px rgba(0,0,0,0.3);
margin: 8px 0;
}
.drill-empty-title { font-size: 16px; font-weight: 700; color: #F8FAFC; margin-bottom: 4px; }
.drill-empty-desc { font-size: 12px; color: #94A3B8; }

/* KIOSK & COMPACT VIEWPORT OVERRIDES */
@media (max-height: 850px) {
  .drill-pinned-section { margin-bottom: 4px; padding-bottom: 4px; }
  .drill-header { padding: 6px 12px; margin-bottom: 4px; }
  .drill-kpi-card { padding: 6px 3px; }
  .drill-kpi-val { font-size: 17px; }
  .drill-m-card { padding: 6px 9px; }
  .drill-detail-table { gap: 2px; }
  .drill-cards-grid {
    gap: 6px;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .drill-cards-grid::-webkit-scrollbar {
    display: none;
    height: 0;
  }
}


/* replay notice: the feed is silent and the cards show the last known state */
.drill-feed-notice { margin-top: 6px; display: inline-block; padding: 3px 10px; border-radius: 4px; font-size: 13px; font-weight: 600;
  color: #fef3c7; background: rgba(245, 158, 11, 0.22); box-shadow: inset 0 0 0 1px #f59e0b; }
